            } else if (rt.eq(g.globals.currLevel, 5.0)) {
                api.room_goto(self, other, k.RM_rTransition1x);
            } else if (rt.eq(g.globals.currLevel, 9.0)) {
                api.room_goto(self, other, k.RM_rTransition2x);
            } else if (rt.eq(g.globals.currLevel, 13.0)) {
                api.room_goto(self, other, k.RM_rTransition3x);
            } else if (rt.eq(g.globals.levelType, 1.0)) {
                api.room_goto(self, other, k.RM_rTransition2);
            } else if (rt.eq(g.globals.levelType, 2.0)) {
                api.room_goto(self, other, k.RM_rTransition3);
            } else if (rt.eq(g.globals.levelType, 3.0)) {
                api.room_goto(self, other, k.RM_rTransition4);
            } else if (rt.eq(g.globals.levelType, 4.0)) {
                api.room_goto(self, other, k.RM_rTransition4);
            } else {
                api.room_goto(self, other, k.RM_rTransition1);
            }
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xSTART])) {
            g.globals.usedShortcut = 0.0;
            g.globals.gameStart = 1.0;
            if (rt.truthy(g.globals.firstTime)) {
                g.globals.currLevel = 0.0;
                g.globals.bombs = 0.0;
                g.globals.rope = 2.0;
                g.globals.firstTime = 0.0;
                api.room_goto(self, other, k.RM_rTutorial);
            } else if (rt.eq(g.globals.levelType, 2.0)) {
                api.room_goto(self, other, k.RM_rLevel2);
            } else {
                api.room_goto(self, other, k.RM_rLevel);
            }
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xTUTORIAL])) {
            g.globals.usedShortcut = 0.0;
            g.globals.gameStart = 1.0;
            g.globals.currLevel = 0.0;
            g.globals.bombs = 0.0;
            g.globals.rope = 2.0;
            api.room_goto(self, other, k.RM_rTutorial);
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xSCORES])) {
            g.globals.gameStart = 0.0;
            if (rt.truthy(g.gml_script_isRoom(self, other, "rTitle"))) {
                g.globals.scoresStart = 0.0;
            } else if (rt.truthy(g.gml_script_isRoom(self, other, "rSun"))) {
                g.globals.scoresStart = 1.0;
            } else if (rt.truthy(g.gml_script_isRoom(self, other, "rMoon"))) {
                g.globals.scoresStart = 2.0;
            } else if (rt.truthy(g.gml_script_isRoom(self, other, "rStars"))) {
                g.globals.scoresStart = 3.0;
            } else {
                g.globals.scoresStart = 0.0;
            }
            api.room_goto(self, other, k.RM_rHighscores);
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xTITLE])) {
            g.globals.gameStart = 0.0;
            if (rt.truthy(g.gml_script_isRoom(self, other, "rHighscores"))) {
                g.globals.titleStart = 1.0;
            } else if (rt.truthy(g.gml_script_isRoom(self, other, "rTutorial"))) {
                g.gml_script_scrClearGlobals(self, other);
                g.globals.titleStart = 3.0;
                g.globals.currLevel = 1.0;
                self.vars[g.VAR_shakeToggle] = 0.0;
                g.globals.darkLevel = 0.0;
                g.globals.snakePit = 0.0;
                g.globals.messageTimer = 0.0;
                g.globals.mini1 = 0.0;
                g.globals.mini2 = 0.0;
                g.globals.mini3 = 0.0;
                g.globals.hasJordans = 0.0;
                g.globals.arrows = 0.0;
            }
            api.room_goto(self, other, k.RM_rTitle);
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xEND])) {
            g.globals.gameStart = 0.0;
            api.room_goto(self, other, k.RM_rEnd);
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xSHORTCUT5])) {
            g.globals.usedShortcut = 1.0;
            g.globals.currLevel = 5.0;
            g.globals.gameStart = 1.0;
