            g.globals.usedShortcut = 1.0;
            g.globals.currLevel = 13.0;
            g.globals.gameStart = 1.0;
            api.room_goto(self, other, k.RM_rLevel);
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xSUN])) {
            g.globals.gameStart = 0.0;
            api.room_goto(self, other, k.RM_rSun);
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xMOON])) {
            g.globals.gameStart = 0.0;
            api.room_goto(self, other, k.RM_rMoon);
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xSTARS])) {
            g.globals.gameStart = 0.0;
            api.room_goto(self, other, k.RM_rStars);
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xCHANGE])) {
            g.globals.isDamsel = rt.b2r(!rt.truthy(g.globals.isDamsel));
            self.vars[g.VAR_active] = 1.0;
            api.iset_depth(self, 50.0);
            self.vars[g.VAR_invincible] = 0.0;
            self.vars[g.VAR_state] = self.vars[g.VAR_STANDING];
            self.vars[g.VAR_facing] = self.vars[g.VAR_LEFT];
            if (rt.truthy(g.globals.isDamsel)) {
                g.globals.isTunnelMan = 0.0;
                api.iset_sprite_index(self, k.SPR_sDamselLeft);
            } else {
                api.iset_sprite_index(self, k.SPR_sStandLeft);
            }
            g.globals.plife = 4.0;
            g.globals.bombs = 4.0;
            g.globals.rope = 4.0;
            self.vars[g.VAR_xVel] = 0.0;
        } else if (rt.eq(self.vars[g.VAR_pExit], self.vars[g.VAR_xCHANGE2])) {
            g.globals.isTunnelMan = rt.b2r(!rt.truthy(g.globals.isTunnelMan));
            if (rt.truthy(g.globals.isTunnelMan)) {
                g.globals.isDamsel = 0.0;
            }
            self.vars[g.VAR_active] = 1.0;
            api.iset_depth(self, 50.0);
            self.vars[g.VAR_invincible] = 0.0;
            self.vars[g.VAR_state] = self.vars[g.VAR_STANDING];
            self.vars[g.VAR_facing] = self.vars[g.VAR_RIGHT];
            if (rt.truthy(g.globals.isTunnelMan)) {
                g.globals.isDamsel = 0.0;
                api.iset_sprite_index(self, k.SPR_sTunnelLeft);
                g.globals.plife = 2.0;
                g.globals.bombs = 0.0;
                g.globals.rope = 0.0;
            } else {
                api.iset_sprite_index(self, k.SPR_sStandLeft);
                g.globals.plife = 4.0;
                g.globals.bombs = 4.0;
                g.globals.rope = 4.0;
            }
            self.vars[g.VAR_xVel] = 0.0;
        }
        g.globals.cleanSolids = 1.0;
    }
